const checkout=document.querySelector('#checkout');
const offers={LUMI10:{discount:10,partner:'DEMO-LUMI',commission:10},PARTNER15:{discount:15,partner:'DEMO-PARTNER',commission:15}};
const money=n=>'US$'+n.toLocaleString('en-SG',{minimumFractionDigits:2,maximumFractionDigits:2});
function quote(percent=0){const discount=Math.round(199900*percent/100);return{discount:discount/100,total:(249800-discount)/100,netSubscription:(199900-discount)/100};}
function clearOffer(){if(!checkout)return;document.querySelector('#discount').textContent=money(0);document.querySelector('#total').textContent=money(2498);document.querySelector('#attribution').textContent='No partner selected.';document.querySelector('#remove').hidden=true;}
for(const button of document.querySelectorAll('[data-open]'))button.addEventListener('click',()=>{if(!checkout)return;document.querySelector('#planTitle').textContent=button.dataset.open;checkout.showModal();});
for(const button of document.querySelectorAll('.close'))button.addEventListener('click',()=>button.closest('dialog').close());
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function apply(){const code=document.querySelector('#code').value.trim().toUpperCase();clearOffer();if(!Object.hasOwn(offers,code)){document.querySelector('#status').textContent=code?'This code is not recognised. Please check it and try again.':'Please enter a discount code.';return;}const offer=offers[code],q=quote(offer.discount);document.querySelector('#discount').textContent='−'+money(q.discount)+' ('+offer.discount+'%)';document.querySelector('#total').textContent=money(q.total);document.querySelector('#status').textContent='Demo offer applied to annual subscription. Equipment rental is unchanged.';document.querySelector('#attribution').textContent='Demo partner: '+offer.partner+'. Illustrative commission: '+offer.commission+'% of discounted subscription ('+money(q.netSubscription)+'), excluding rental, tax and shipping. Estimated commission: '+money(q.netSubscription*offer.commission/100)+'. Refunds reverse commission. Not a live settlement.';document.querySelector('#remove').hidden=false;}
if(checkout){document.querySelector('#apply').addEventListener('click',apply);document.querySelector('#code').addEventListener('keydown',e=>{if(e.key==='Enter')apply();});document.querySelector('#remove').addEventListener('click',()=>{clearOffer();document.querySelector('#code').value='';document.querySelector('#status').textContent='Code removed.';});}
document.querySelector('#privacy')?.addEventListener('click',e=>{e.preventDefault();document.querySelector('#privacyDialog').showModal();});
for(const button of document.querySelectorAll('[data-filter]'))button.addEventListener('click',()=>{for(const b of document.querySelectorAll('[data-filter]')){b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));}for(const study of document.querySelectorAll('[data-category]'))study.hidden=button.dataset.filter!=='all'&&study.dataset.category!==button.dataset.filter;});
